<script setup>
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';
import Icon from './HelmLabIcon.vue';
import Confirm from './LocalLabConfirm.vue';
import {apiFetch} from './store.js';
import {CONFIRMATION_TEXT} from './confirmation.mjs';
import {cacheBytes} from './cache-lab.mjs';
import {testPackageSummaries,openTestPackage,createClusterTestPackage} from './test-packages-store.mjs';
import {pullRequestReference} from './test-packages.mjs';
import {clusterWorkspaces,renameCluster,clusterDisplayName,openClusterTestRun,openClusterTestPlan,openClusterCache,prepareClusterTest,prepareClusterCache,notifyClusterDataChanged,refreshClusterWorkspaces} from './cluster-workspace-store.mjs';
const props=defineProps({cluster:{type:Object,required:true},embedded:Boolean});
const entry=computed(()=>clusterWorkspaces.value.find(item=>item.id===props.cluster.id)||props.cluster);
const displayName=computed(()=>clusterDisplayName(entry.value.id,entry.value.name||props.cluster.name||entry.value.url||'Cluster workspace'));
const testRuns=computed(()=>[...(entry.value.testRuns||[])].sort((a,b)=>new Date(b.startedAt)-new Date(a.startedAt)));
const testPlans=computed(()=>[...(entry.value.testPlans||[])].sort((a,b)=>new Date(b.savedAt)-new Date(a.savedAt)));
const cacheWorkspaces=computed(()=>entry.value.cacheWorkspaces||[]);
const snapshots=computed(()=>[...(entry.value.snapshots||[])].sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)));
const statistics=computed(()=>({passed:testRuns.value.filter(run=>run.status==='passed').length,failed:testRuns.value.filter(run=>run.status==='failed').length,running:testRuns.value.filter(run=>run.status==='running').length}));
const totalBytes=computed(()=>snapshots.value.reduce((sum,item)=>sum+(Number(item.bytes)||0),0));
const endpoint=computed(()=>entry.value.url||props.cluster.rancherUrl||'');
const linkedPackages=computed(()=>testPackageSummaries.value.map(pkg=>({...pkg,linkedSessions:(pkg.sessions||[]).filter(session=>session.environment?.clusterId===entry.value.id)})).filter(pkg=>pkg.linkedSessions.length));
const editingName=ref(false),nickname=ref(''),nameInput=ref(null),editingRecord=ref(null),recordInput=ref(null),pending=ref(''),error=ref(''),notice=ref(''),dialog=ref(null),showAllRuns=ref(false),showAllSnapshots=ref(false);
const visibleRuns=computed(()=>showAllRuns.value?testRuns.value:testRuns.value.slice(0,5));
const controllers=new Set();
const date=value=>value?new Date(value).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'Date not recorded';
const statusLabel=value=>String(value||'recorded').replaceAll('_',' ');
const workspaceSnapshots=id=>snapshots.value.filter(snapshot=>snapshot.workspace===id);
const visibleSnapshots=id=>showAllSnapshots.value?workspaceSnapshots(id):workspaceSnapshots(id).slice(0,4);
async function perform(label,task){if(pending.value)return false;pending.value=label;error.value='';notice.value='';try{await task();return true;}catch(failure){error.value=failure.message||'The change could not be saved.';return false;}finally{pending.value='';}}
async function request(endpoint,data){const controller=new AbortController();controllers.add(controller);const timeout=setTimeout(()=>controller.abort(),45000);try{const response=await apiFetch(endpoint,{method:'POST',signal:controller.signal,body:JSON.stringify(data)});if(!response.ok)throw new Error(await response.text()||'The change could not be saved.');return await response.json();}catch(failure){if(failure.name==='AbortError')throw new Error('The request timed out. Refresh this workspace before retrying.');throw failure;}finally{clearTimeout(timeout);controllers.delete(controller);}}
async function editName(){nickname.value=entry.value.nickname||'';editingName.value=true;await nextTick();nameInput.value?.focus();}
async function saveName(){const id=entry.value.id;if(await perform('nickname',()=>renameCluster(id,nickname.value.trim()))){editingName.value=false;notice.value=nickname.value.trim()?'Nickname updated throughout Runway.':'Original cluster name restored.';}}
async function editRecord(kind,record){editingRecord.value={kind,id:record.id,workspace:record.workspace,name:record.name||''};await nextTick();recordInput.value?.focus();}
async function saveRecord(){const record=editingRecord.value;if(!record?.name.trim())return;const snapshot=record.kind==='snapshot';if(await perform('rename',async()=>{await request(snapshot?'/api/cache-lab':'/api/test-lab',snapshot?{action:'rename-snapshot',workspace:record.workspace,snapshot:record.id,name:record.name.trim()}:{action:record.kind==='plan'?'rename-plan':'rename-run',id:record.id,name:record.name.trim()});notifyClusterDataChanged();await refreshClusterWorkspaces({fresh:true});})){editingRecord.value=null;notice.value=`Name saved in this workspace and ${snapshot?'Cache':'Test'} Lab.`;}}
function removeRecord(kind,record){
 const snapshot=kind==='snapshot',workspace=kind==='workspace',plan=kind==='plan';
 dialog.value={key:`${kind}:${record.id}`,title:workspace?'Delete this Cache Lab workspace?':snapshot?'Delete this snapshot?':plan?'Delete this saved test plan?':'Delete this local test result?',message:workspace?`Permanently remove “${record.name}”, its ${workspaceSnapshots(record.id).length} snapshots, saved connection, queries, and notes. Live Rancher resources and original imported files stay in place.`:snapshot?`Permanently remove “${record.name}” (${cacheBytes(record.bytes)}) from this workspace and Cache Lab. The live database and original imported file stay in place.`:plan?`Remove “${record.name}” and its saved Keychain configuration. Existing test results and Rancher resources stay in place.`:`Remove “${record.name}” (${record.id}) and its local activity log from this workspace and Test Lab. This does not clean up resources in Rancher.`,endpoint:snapshot||workspace?'/api/cache-lab':'/api/test-lab',payload:snapshot?{action:'delete-snapshot',workspace:record.workspace,snapshot:record.id}:workspace?{action:'delete-workspace',workspace:record.id}:{action:plan?'delete-plan':'delete-run',id:record.id}};
}
async function confirmRemoval(){const target=dialog.value;if(!target)return;if(await perform('delete',async()=>{await request(target.endpoint,{...target.payload,confirm:CONFIRMATION_TEXT});notifyClusterDataChanged();await refreshClusterWorkspaces();})){dialog.value=null;notice.value='Removed from the shared library.';}}
watch(()=>props.cluster.id,()=>{editingName.value=false;editingRecord.value=null;dialog.value=null;error.value='';notice.value='';showAllRuns.value=false;showAllSnapshots.value=false;});
onBeforeUnmount(()=>controllers.forEach(controller=>controller.abort()));
</script>

<template>
 <section class="cluster-workspace" :class="{'is-embedded':embedded}" :aria-label="`${displayName} workspace`" :data-cluster-workspace-id="entry.id" tabindex="-1">
  <header class="cw-heading">
   <div class="cw-identity"><span class="cw-symbol"><Icon name="layers"/></span><div><span class="cw-eyebrow">{{ embedded?'CONNECTED WORKSPACE':'CLUSTER WORKSPACE' }}</span><h3>{{ embedded?'Tests, snapshots, and the story so far.':displayName }}</h3><p v-if="embedded">One home for this cluster’s saved work. Names and files stay in sync across labs.</p><p v-else>{{ endpoint||'No Rancher URL recorded' }}</p></div></div>
   <span v-if="!embedded" class="cw-badge">{{ entry.archived?'Retained history':'External Rancher' }}</span>
  </header>
  <div class="cw-identity-bar"><div><span class="cw-eyebrow">{{ entry.nickname?'NICKNAME':'CLUSTER NAME' }}</span><strong>{{ displayName }}</strong><span v-if="entry.version" class="cw-muted">{{ entry.version }}</span></div><button type="button" class="cw-link" :disabled="!!pending" @click="editingName?editingName=false:editName()"><Icon name="sliders"/>{{ editingName?'Cancel naming':'Edit nickname' }}</button></div>
  <form v-if="editingName" class="cw-name-editor" @submit.prevent="saveName"><label :for="`cluster-nickname-${entry.id}`">Nickname <span>optional</span></label><div><input :id="`cluster-nickname-${entry.id}`" ref="nameInput" v-model="nickname" maxlength="80" :placeholder="entry.name||'Use the original cluster name'" :disabled="!!pending"/><button type="submit" class="cw-button" :disabled="!!pending">{{ pending==='nickname'?'Saving…':'Save name' }}</button></div><small>Leave blank to restore the original name. Stable cluster IDs and version labels stay unchanged.</small></form>
  <div class="cw-provenance"><span>Cluster <code>{{ entry.id }}</code></span><span v-if="entry.runId">Run <code>{{ entry.runId }}</code></span><span v-if="entry.role">{{ entry.role }}</span></div>
  <div v-if="error" class="cw-feedback cw-error" role="alert"><Icon name="signal"/><span>{{ error }}</span><button type="button" aria-label="Dismiss workspace error" @click="error=''">×</button></div><p v-if="notice" class="cw-feedback" role="status"><Icon name="check"/>{{ notice }}</p>
  <div class="cw-columns">
   <section class="cw-lab"><header><span class="cw-lab-icon"><Icon name="flask"/></span><div><h4>Test Lab</h4><p>{{ testRuns.length }} local {{ testRuns.length===1?'run':'runs' }} · {{ testPlans.length }} saved {{ testPlans.length===1?'plan':'plans' }}</p></div><button type="button" class="cw-button cw-primary" :disabled="!endpoint||!!pending" @click="prepareClusterTest(entry.id)">New test <Icon name="arrow"/></button></header>
    <div v-if="testRuns.length" class="cw-test-stats" aria-label="Local test run outcomes"><span data-tone="passed"><strong>{{ statistics.passed }}</strong> passed</span><span data-tone="failed"><strong>{{ statistics.failed }}</strong> failed</span><span data-tone="running"><strong>{{ statistics.running }}</strong> running</span></div>
    <div v-if="!testRuns.length&&!testPlans.length" class="cw-empty"><Icon name="flask"/><strong>Your next finding starts here.</strong><p>Choose a suite or a single test. This cluster will already be selected, and results will return here.</p><small v-if="!endpoint">A Rancher URL is needed to prepare a test.</small></div>
    <div v-if="testRuns.length" class="cw-list"><div class="cw-list-label">RECENT RESULTS</div><article v-for="run in visibleRuns" :key="run.id" class="cw-record"><button type="button" class="cw-record-main" @click="openClusterTestRun(run.id)"><span class="cw-status" :data-status="run.status">{{ statusLabel(run.status) }}</span><strong>{{ run.name||run.id }}</strong><small>{{ date(run.startedAt) }} · {{ run.results?.length||0 }} result events</small></button><div class="cw-record-actions"><button type="button" :aria-label="`Rename test result ${run.name||run.id}`" :disabled="!!pending" @click="editRecord('run',run)"><Icon name="sliders"/></button><button type="button" :aria-label="`Delete test result ${run.name||run.id}`" :disabled="!!pending||run.status==='running'" @click="removeRecord('run',run)"><Icon name="trash"/></button></div></article><button v-if="testRuns.length>5" type="button" class="cw-link cw-more" @click="showAllRuns=!showAllRuns">{{ showAllRuns?'Show recent results':`Show all ${testRuns.length} results` }}</button></div>
    <details v-if="testPlans.length" class="cw-plans"><summary><Icon name="bookmark"/>Saved plans <span>{{ testPlans.length }}</span><Icon name="chevron"/></summary><article v-for="plan in testPlans" :key="plan.id" class="cw-record"><button type="button" class="cw-record-main" @click="openClusterTestPlan(plan.id)"><strong>{{ plan.name||plan.id }}</strong><small>{{ plan.selection?.length||0 }} selections · {{ date(plan.savedAt) }}</small></button><div class="cw-record-actions"><button type="button" :aria-label="`Rename saved plan ${plan.name||plan.id}`" :disabled="!!pending" @click="editRecord('plan',plan)"><Icon name="sliders"/></button><button type="button" :aria-label="`Delete saved plan ${plan.name||plan.id}`" :disabled="!!pending" @click="removeRecord('plan',plan)"><Icon name="trash"/></button></div></article></details>
   </section>
   <section class="cw-lab"><header><span class="cw-lab-icon"><Icon name="database"/></span><div><h4>Cache Lab</h4><p>{{ snapshots.length }} {{ snapshots.length===1?'snapshot':'snapshots' }} · {{ cacheBytes(totalBytes) }}</p></div><button type="button" class="cw-button cw-primary" :disabled="!endpoint||!!pending" @click="prepareClusterCache(entry.id)">Capture <Icon name="arrow"/></button></header>
    <div v-if="!cacheWorkspaces.length" class="cw-empty"><Icon name="database"/><strong>A saved moment, ready to explore.</strong><p>Connect this Rancher to capture its live SQL cache. Inspect tables, save queries, and compare snapshots in Cache Lab.</p><small v-if="!endpoint">A Rancher URL is needed to prepare a connection.</small></div>
    <div v-else class="cw-cache-list"><section v-for="workspace in cacheWorkspaces" :key="workspace.id" class="cw-cache-workspace"><header><button type="button" class="cw-link" @click="openClusterCache(workspace.id)"><Icon name="folder"/><strong>{{ workspace.name }}</strong><Icon name="arrow"/></button><button type="button" class="cw-icon-button" :aria-label="`Delete cache workspace ${workspace.name}`" :disabled="!!pending||workspace.active" :title="workspace.active?'Wait for this workspace’s capture to finish.':undefined" @click="removeRecord('workspace',workspace)"><Icon name="trash"/></button></header><p v-if="!workspaceSnapshots(workspace.id).length" class="cw-cache-empty">Connected library · no saved snapshots yet.</p><article v-for="snapshot in visibleSnapshots(workspace.id)" :key="snapshot.id" class="cw-record"><button type="button" class="cw-record-main" @click="openClusterCache(workspace.id,snapshot.id)"><strong><Icon name="database"/>{{ snapshot.name }}</strong><small>{{ date(snapshot.createdAt) }} · {{ cacheBytes(snapshot.bytes) }} · {{ snapshot.tables||0 }} tables</small></button><div class="cw-record-actions"><button type="button" :aria-label="`Rename snapshot ${snapshot.name}`" :disabled="!!pending" @click="editRecord('snapshot',snapshot)"><Icon name="sliders"/></button><button type="button" :aria-label="`Delete snapshot ${snapshot.name}`" :disabled="!!pending||workspace.active" :title="workspace.active?'Wait for this workspace’s capture to finish.':undefined" @click="removeRecord('snapshot',snapshot)"><Icon name="trash"/></button></div></article></section><button v-if="cacheWorkspaces.some(workspace=>workspaceSnapshots(workspace.id).length>4)" type="button" class="cw-link cw-more" @click="showAllSnapshots=!showAllSnapshots">{{ showAllSnapshots?'Show recent snapshots':'Show every snapshot' }}</button></div>
   </section>
  </div>
  <section class="cw-lab cw-packages"><header><span class="cw-lab-icon"><Icon name="folder"/></span><div><h4>Test Packages</h4><p>Manual cases, preserved sessions, and evidence linked to this cluster.</p></div><button type="button" class="cw-button cw-primary" @click="createClusterTestPackage(entry.id)">New package <Icon name="arrow"/></button></header><p v-if="!linkedPackages.length" class="cw-cache-empty">Start a package, then record a session on this cluster. Your reproduction and validation history will appear here.</p><div v-else class="cw-list"><article v-for="pkg in linkedPackages" :key="pkg.id" class="cw-record"><button type="button" class="cw-record-main" @click="openTestPackage(pkg.id)"><strong>{{ pkg.title }}</strong><small>{{ statusLabel(pkg.status) }} · {{ pkg.linkedSessions.length }} linked sessions<template v-if="pullRequestReference(pkg.fixUrl)"> · fix {{ pullRequestReference(pkg.fixUrl).short }}</template></small></button><button type="button" class="cw-link" @click="openTestPackage(pkg.id,pkg.linkedSessions.at(-1)?.id)">Latest session <Icon name="arrow"/></button></article></div></section>
  <form v-if="editingRecord" class="cw-name-editor" @submit.prevent="saveRecord"><label :for="`cluster-record-name-${entry.id}`">{{ editingRecord.kind==='snapshot'?'Snapshot name':editingRecord.kind==='plan'?'Saved plan name':'Test result name' }}</label><div><input :id="`cluster-record-name-${entry.id}`" ref="recordInput" v-model="editingRecord.name" maxlength="100" :disabled="!!pending"/><button type="submit" class="cw-button" :disabled="!!pending||!editingRecord.name.trim()">Save name</button><button type="button" class="cw-link" :disabled="!!pending" @click="editingRecord=null">Cancel</button></div></form>
  <Confirm v-if="dialog" :key="dialog.key" :title="dialog.title" :message="dialog.message" :busy="!!pending" button-label="Delete locally" @confirm="confirmRemoval" @cancel="dialog=null"/>
  <footer class="cw-footer"><Icon name="branch"/>Lab records stay in sync everywhere. Evidence explicitly attached to a test package is preserved separately when its source is cleaned up.</footer>
 </section>
</template>

<style scoped>
.cluster-workspace{color:var(--runway-ink);background:var(--runway-card);border:1px solid var(--runway-border);border-radius:18px;padding:24px;min-width:0;scroll-margin-top:100px;font-size:13px;line-height:1.55}.cluster-workspace.is-embedded{margin-top:20px;background:var(--runway-soft)}.cluster-workspace *{box-sizing:border-box}.cluster-workspace button,.cluster-workspace input{font:inherit}.cluster-workspace button{cursor:pointer}.cluster-workspace button:disabled{opacity:.45;cursor:not-allowed}.cluster-workspace :focus-visible{outline:2px solid var(--runway-accent);outline-offset:3px}.cluster-workspace svg{width:17px;height:17px;flex-shrink:0}.cluster-workspace h3,.cluster-workspace h4,.cluster-workspace p{margin:0}.cw-heading,.cw-identity,.cw-identity-bar,.cw-lab>header,.cw-cache-workspace>header{display:flex;align-items:center;gap:14px}.cw-heading{align-items:flex-start;justify-content:space-between}.cw-identity{min-width:0;align-items:flex-start}.cw-symbol{display:grid;place-items:center;width:42px;height:42px;flex-shrink:0;border:1px solid var(--runway-border);border-radius:12px;color:var(--runway-accent);background:var(--runway-raised)}.cw-symbol svg{width:23px;height:23px}.cw-eyebrow,.cw-list-label{font-size:9px;font-weight:700;letter-spacing:.15em;color:var(--runway-muted)}.cw-heading h3{font-size:20px;letter-spacing:-.03em;line-height:1.3;margin:5px 0}.cw-heading p{color:var(--runway-muted);font-size:12px;overflow-wrap:anywhere}.cw-badge{border:1px solid var(--runway-border);border-radius:99px;padding:5px 10px;font-size:10px;white-space:nowrap;color:var(--runway-muted)}.cw-identity-bar{justify-content:space-between;margin-top:22px;padding:14px 0 10px;border-top:1px solid var(--runway-border)}.cw-identity-bar>div{display:flex;align-items:center;flex-wrap:wrap;gap:12px;min-width:0}.cw-identity-bar strong{overflow-wrap:anywhere}.cw-muted,.cw-provenance,.cw-footer{color:var(--runway-muted)}.cw-provenance{display:flex;gap:16px;flex-wrap:wrap;font-size:10px;overflow-wrap:anywhere}.cw-provenance code{font-size:10px}.cw-link,.cw-icon-button,.cw-record-actions button{display:inline-flex;align-items:center;gap:7px;background:transparent;border:0;color:var(--runway-accent);padding:5px}.cw-icon-button,.cw-record-actions button{color:var(--runway-muted);border-radius:7px;min-width:32px;min-height:32px;justify-content:center}.cw-link:hover{text-decoration:underline}.cw-icon-button:hover,.cw-record-actions button:hover{background:var(--runway-raised);color:var(--runway-ink)}.cw-name-editor{padding:15px;background:var(--runway-card);border:1px solid var(--runway-border);border-radius:10px;margin:10px 0}.cw-name-editor label{display:block;font-weight:650;font-size:12px;margin-bottom:7px}.cw-name-editor label span,.cw-name-editor small{color:var(--runway-muted);font-weight:400}.cw-name-editor>div{display:flex;gap:10px}.cw-name-editor input{border:1px solid var(--runway-border);background:var(--runway-soft);border-radius:8px;color:var(--runway-ink);padding:9px 12px;min-width:0;flex:1}.cw-name-editor small{display:block;margin-top:8px;font-size:11px}.cw-button{display:inline-flex;align-items:center;justify-content:center;gap:8px;border:1px solid var(--runway-border);border-radius:8px;background:var(--runway-raised);color:var(--runway-ink);padding:8px 12px;white-space:nowrap;font-size:11px!important;font-weight:650!important}.cw-primary{color:var(--runway-accent);background:color-mix(in srgb,var(--runway-accent) 8%,var(--runway-card));border-color:color-mix(in srgb,var(--runway-accent) 26%,var(--runway-border))}.cw-packages{margin-top:16px}.cw-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.cw-lab{min-width:0;border:1px solid var(--runway-border);border-radius:13px;background:var(--runway-card);overflow:hidden}.cw-lab>header{padding:17px;border-bottom:1px solid var(--runway-border);gap:11px}.cw-lab>header>div{flex:1;min-width:0}.cw-lab h4{font-size:15px;letter-spacing:-.02em}.cw-lab header p{color:var(--runway-muted);font-size:10px;margin-top:3px}.cw-lab-icon{color:var(--runway-accent)}.cw-test-stats{display:flex;gap:18px;padding:12px 17px;border-bottom:1px solid var(--runway-border);font-size:11px;color:var(--runway-muted)}.cw-test-stats strong{font-size:16px;margin-right:4px}.cw-test-stats [data-tone=passed] strong{color:var(--runway-accent)}.cw-test-stats [data-tone=failed] strong{color:var(--runway-error)}.cw-test-stats [data-tone=running] strong{color:var(--runway-gold)}.cw-empty{padding:28px 24px;display:grid;gap:9px;justify-items:start}.cw-empty>svg{width:26px;height:26px;color:var(--runway-muted);margin-bottom:4px}.cw-empty p,.cw-empty small{font-size:12px;color:var(--runway-muted);max-width:440px}.cw-list,.cw-cache-list{max-height:390px;overflow:auto;overscroll-behavior:contain;scrollbar-gutter:stable}.cw-list-label{padding:13px 17px 4px}.cw-record{display:flex;align-items:center;gap:10px;margin:0 12px;padding:10px 0;border-bottom:1px solid var(--runway-border)}.cw-record:last-child{border-bottom:0}.cw-record-main{display:grid;gap:4px;min-width:0;flex:1;text-align:left;border:0;background:transparent;color:var(--runway-ink);padding:4px 5px;border-radius:7px}.cw-record-main:hover{background:var(--runway-soft)}.cw-record-main strong{font-size:12px;overflow-wrap:anywhere;display:flex;align-items:center;gap:8px}.cw-record-main small{color:var(--runway-muted);font-size:10px;overflow-wrap:anywhere}.cw-status{width:fit-content;border-radius:4px;padding:2px 6px;background:var(--runway-soft);color:var(--runway-muted);text-transform:uppercase;font-weight:700;font-size:8px;letter-spacing:.07em}.cw-status[data-status=passed]{color:var(--runway-accent)}.cw-status[data-status=failed]{color:var(--runway-error)}.cw-status[data-status=running]{color:var(--runway-gold)}.cw-record-actions{display:flex;gap:2px}.cw-plans{border-top:1px solid var(--runway-border);max-height:300px;overflow:auto}.cw-plans summary{padding:13px 17px;cursor:pointer;display:flex;gap:8px;align-items:center;color:var(--runway-muted);font-size:11px;font-weight:600}.cw-plans summary span{margin-left:auto}.cw-more{margin:8px 12px 10px;font-size:11px!important}.cw-cache-workspace>header{padding:10px 12px;background:var(--runway-soft);justify-content:space-between}.cw-cache-workspace>header .cw-link{min-width:0;font-size:11px}.cw-cache-workspace>header strong{overflow-wrap:anywhere}.cw-cache-empty{color:var(--runway-muted);font-size:11px;padding:20px}.cw-footer{display:flex;align-items:flex-start;gap:8px;border-top:1px solid var(--runway-border);margin-top:18px;padding-top:13px;font-size:10px}.cw-feedback{display:flex;align-items:center;gap:10px;border:1px solid var(--runway-border);padding:12px;border-radius:9px;margin-top:13px!important;color:var(--runway-accent);font-size:12px}.cw-error{color:var(--runway-error)}.cw-feedback button{margin-left:auto;background:transparent;border:0;color:inherit}@media(max-width:1000px){.cw-columns{grid-template-columns:1fr}}@media(max-width:640px){.cluster-workspace{padding:17px}.cw-heading,.cw-identity-bar{align-items:flex-start;flex-direction:column}.cw-lab>header{flex-wrap:wrap}.cw-name-editor>div{flex-wrap:wrap}.cw-name-editor input{flex-basis:100%}.cw-provenance{gap:7px 14px}.cw-heading h3{font-size:18px}}
</style>
